 public static Catalogue catalogue(JdbcTemplate jdbc){String revision="synthetic-"+UUID.randomUUID();long dataset=jdbc.queryForObject("INSERT INTO activity_dataset(name,release_name,revision,source_url,content_sha256,source_note,min_age,max_age,verified) VALUES('SYNTHETIC_WORKOUT_TEST_ONLY','test',?,'https://example.test/synthetic',?,'Explicit synthetic coefficients, not official source data',19,59,true) RETURNING id",Long.class,revision,"b".repeat(64));long strengthType=type(jdbc,dataset,"99901","3.5"),cardioType=type(jdbc,dataset,"99902","5");long strength=option(jdbc,"STRENGTH",strengthType,revision),cardio=option(jdbc,"ACTIVITY",cardioType,revision),unavailable=option(jdbc,"ACTIVITY",null,revision);var movements=new ArrayList<Long>();for(int i=0;i<3;i++)movements.add(jdbc.queryForObject("INSERT INTO movement_catalogue(movement_key,revision,active,display_name,aliases,body_region,equipment_type,load_basis,allowed_fields,review_status,default_period_option_id) VALUES(?,?,true,?,'[]','CHEST','BARBELL','TOTAL_BARBELL','[\"setCount\",\"repetitions\",\"loadKg\"]','REVIEWED',?) RETURNING id",Long.class,"synthetic-"+UUID.randomUUID(),revision,"Synthetic movement "+i,strength));return new Catalogue(strength,cardio,unavailable,List.copyOf(movements));}
